NIGHT = 'At night, under cool blue moonlight.'

def listed(id, kind, what, box, madein, src=None, shared=True):
    r = dict(id=id, kind=kind, what=what, box=box, shared=shared, made=False, madein=madein)
    if src: r['src'] = src
    if shared is not True: r['shared'] = f'no (listed only: {madein})'
    return r

